sys_script.script:
(function executeRule(current, previous /*null when async*/) {
    // Admins and Placement Officers bypass this restriction and see all records
    if (gs.hasRole('admin') || gs.hasRole('x_snc_college_pl_0.placement_officer')||gs.hasRole('x_snc_college_pl_0.placement_admin')) {
        return;
    }

    var userId = gs.getUserID();

    // Check if the user has an interviewer role or if they match an interviewer profile
    // (You can also add a specific role check here if Company HR has a dedicated role)

    // We can use an OR query condition to handle multiple user types:
    // 1. If the user is an Interviewer/Company HR assigned to the record.
    // 2. If the user is a Student linked via their application.

    // First, find applications belonging to the logged-in student
    var appGr = new GlideRecord('x_snc_college_pl_0_application');
    appGr.addQuery('student.user', userId);
    appGr.query();

    var appIds = [];
    while (appGr.next()) {
        appIds.push(appGr.getUniqueValue());
    }

    // Build a query using addEncodedQuery or addCondtion with an OR setup
    // This ensures Company HR sees their assigned interviews, and students see theirs.
    var qc = current.addQuery('interviewer', userId);

    if (appIds.length > 0) {
        qc.addOrCondition('application', 'IN', appIds);
    } else {
        // If they are neither an interviewer for any record nor have applications, block viewing entirely
        if (appIds.length === 0 && !isInterviewer(userId)) { // optional guard
            // If they are strictly a student with no apps and not an interviewer:
            current.addQuery('sys_id', 'none');
        }
    }

})(current, previous);
